questionvariables.text:
rlist: [[6.4,3.6,"edge",["half","never","edge","vert"]],[8.6,3.3,"half",["never","vert","half","edge"]],[6.6,1.4,"vert",["never","edge","half","vert"]],[5.9,3.9,"edge",["half","never","edge","vert"]],[8.3,3.2,"half",["never","edge","vert","half"]],[6.1,2.7,"vert",["edge","vert","half","never"]],[8.7,2.1,"edge",["vert","half","never","edge"]],[4.1,1,"half",["edge","never","vert","half"]],[8.4,1.9,"vert",["half","edge","never","vert"]],[9,3.1,"edge",["half","edge","never","vert"]]];
/* Design: find the mistake in a roof angle. er: edge (used OC), half (whole side for OM), vert (angle with the vertical). The "never" statement is never correct. Statement order is permuted per entry, correct never first. Source: original, after an idea in SMP Book 5 (Metric), Chapter 7, section 2. */
ix: 1+rand(10); RR: rlist[ix];
ss: RR[1]; hh: RR[2]; er: RR[3]; ORD: RR[4];
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100); d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2);
NA: -999; NB: -888;
STM(k) := if k = "edge" then "He used OC, which goes to the corner C. The line in the face perpendicular to BC goes to its midpoint M, so he should have used OM."
  else if k = "half" then "He used the whole side for OM. M is the midpoint of BC, so OM is half the side."
  else if k = "vert" then "He found the angle between the face and the vertical line VO, not the angle between the face and the base."
  else "He should have used the sloping edge VC instead of the height VO.";
opts: makelist([k, is(k = er), STM(k)], k, ORD);
hs: ss/2; OCr: r2(ss*sqrt(2)/2);
th: float(atan(hh/hs)*180/%pi);
vE: r1(float(atan(hh/OCr)*180/%pi)); vH: r1(float(atan(hh/ss)*180/%pi)); vV: r1(float(atan(hs/hh)*180/%pi));
val(k) := if k = "edge" then vE else if k = "half" then vH else vV;
shw: val(er);
oth: delete(er, ["edge","half","vert"]); k1: oth[1]; k2: oth[2]; ov1: val(k1); ov2: val(k2);
e1: is(k1 = "edge"); hf1: is(k1 = "half"); e2: is(k2 = "edge"); hf2: is(k2 = "half");
isE: is(er = "edge"); isHf: is(er = "half");
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
